import React, { useState } from 'react';

const Recharge = ({ onRecharge, balance }) => {
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');

    const plans = [
        { amount: 500, credits: 50000, label: '₹50,000' },
        { amount: 1000, credits: 110000, label: '₹1,10,000' },
        { amount: 5000, credits: 600000, label: '₹6,00,000' }
    ];

    const handleRecharge = async (plan) => {
        setLoading(true);
        try {
            const response = await fetch('http://localhost:5000/api/recharge', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ amount: plan.amount })
            });
            const data = await response.json();
            setMessage(data.message || data.error);
            if (data.balance !== undefined && onRecharge) {
                onRecharge(data.balance);
            }
        } catch (error) {
            setMessage('Error recharging');
        }
        setLoading(false);
    };

    return (
        <div style={{
            background: '#141b2b',
            padding: '30px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c',
            maxWidth: '500px'
        }}>
            <h3 style={{ marginBottom: '10px', color: '#e0e6ed' }}>💳 Recharge Demo Account</h3>
            <p style={{ color: '#8a9bb5', marginBottom: '5px' }}>
                Get more demo credits to trade with!
            </p>
            {balance !== undefined && (
                <p style={{ color: '#4CAF50', marginBottom: '20px', fontSize: '14px' }}>
                    Current Balance: ₹{balance.toFixed(2)}
                </p>
            )}
            
            {message && (
                <div style={{
                    padding: '10px',
                    marginBottom: '15px',
                    borderRadius: '6px',
                    background: '#1a2332',
                    textAlign: 'center',
                    color: '#e0e6ed'
                }}>
                    {message}
                </div>
            )}
            
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px' }}>
                {plans.map((plan) => (
                    <button
                        key={plan.amount}
                        onClick={() => handleRecharge(plan)}
                        disabled={loading}
                        style={{
                            padding: '20px',
                            background: '#1a2332',
                            border: '1px solid #2a3a5c',
                            borderRadius: '8px',
                            color: 'white',
                            cursor: 'pointer',
                            textAlign: 'center',
                            transition: 'all 0.3s',
                            opacity: loading ? 0.5 : 1
                        }}
                        onMouseEnter={(e) => {
                            e.target.style.background = '#2a3a5c';
                            e.target.style.borderColor = '#4CAF50';
                        }}
                        onMouseLeave={(e) => {
                            e.target.style.background = '#1a2332';
                            e.target.style.borderColor = '#2a3a5c';
                        }}
                    >
                        <div style={{ fontSize: '20px', fontWeight: 'bold', color: '#4CAF50' }}>
                            ₹{plan.amount}
                        </div>
                        <div style={{ fontSize: '14px', color: '#8a9bb5', marginTop: '5px' }}>
                            Get {plan.label}
                        </div>
                    </button>
                ))}
            </div>
        </div>
    );
};

export default Recharge;
